// @ts-nocheck -- route search types are generated by the embedded app.
//
// Evidence explorer: EVERYTHING the learner ever uploaded to Aptem (files and
// notes, all mirrored to Azure), classified by what the document actually IS —
// learners upload into the wrong slot often enough that the slot name is only
// a provisional hint until the content classifier's verdict lands. Misfiled
// uploads (content contradicts the slot) are flagged loudly.
import { useMemo, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import Swal from "sweetalert2";
import { AlertTriangle, Check, FileText, LoaderCircle, Pencil, StickyNote, Undo2, Upload, X } from "lucide-react";
import {
  editEvidence,
  getEvidenceList,
  replaceEvidenceFile,
  reviewEvidence,
  transferEvidence,
  type EvidenceCategory,
  type EvidenceItem,
} from "@/features/audit/learner-log-pro-copy/lib/manualApi";

export const Route = createFileRoute("/evidence")({
  validateSearch: (search: Record<string, unknown>) => ({
    learner: typeof search.learner === "string" ? search.learner : typeof search.learner === "number" ? String(search.learner) : "",
    period: typeof search.period === "string" ? search.period : "",
  }),
  component: EvidenceExplorerPage,
});

const CATEGORY_LABELS: Record<EvidenceCategory, string> = {
  assignment: "Assignments",
  attendance_reflection: "Attendance reflections",
  lms_activity: "LMS activities",
  review: "Reviews",
  work_product: "Work products",
  administrative: "Administrative",
  other: "Other",
};

const CATEGORY_BADGES: Record<EvidenceCategory, string> = {
  assignment: "bg-[#182d48]/10 text-[#182d48]",
  attendance_reflection: "bg-amber-500/15 text-amber-700",
  lms_activity: "bg-primary/10 text-primary",
  review: "bg-success/15 text-success",
  work_product: "bg-[#673ab7]/15 text-[#673ab7]",
  administrative: "bg-muted text-muted-foreground",
  other: "bg-destructive/10 text-destructive",
};

function hoursLabel(value: number) {
  return value ? `${Math.round(value * 100) / 100} h` : "—";
}

function EvidenceExplorerPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { learner, period } = Route.useSearch();
  const [categoryFilter, setCategoryFilter] = useState<EvidenceCategory | "all">("all");
  const [misfiledOnly, setMisfiledOnly] = useState(false);
  const [busyId, setBusyId] = useState<number | null>(null);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDraft, setEditDraft] = useState({ display_name: "", category: "" as EvidenceCategory, evidence_date: "" });
  const replaceInputRef = useRef<HTMLInputElement | null>(null);
  const replaceTargetRef = useRef<EvidenceItem | null>(null);

  function startEdit(item: EvidenceItem) {
    setEditingId(item.evidence_id);
    setEditDraft({ display_name: item.name, category: item.category, evidence_date: item.date ?? "" });
  }

  async function saveEdit() {
    if (editingId == null) return;
    if (!editDraft.display_name.trim()) {
      return void Swal.fire({ icon: "error", title: "Check the edit", text: "The name cannot be empty." });
    }
    setBusyId(editingId);
    try {
      await editEvidence(editingId, {
        display_name: editDraft.display_name.trim(),
        category: editDraft.category,
        evidence_date: editDraft.evidence_date,
      });
      await queryClient.invalidateQueries({ queryKey: ["evidence-list"] });
      setEditingId(null);
    } catch (error) {
      await Swal.fire({ icon: "error", title: "Could not save the edit", text: error instanceof Error ? error.message : "" });
    } finally {
      setBusyId(null);
    }
  }

  function pickReplacement(item: EvidenceItem) {
    replaceTargetRef.current = item;
    replaceInputRef.current?.click();
  }

  async function handleReplacePicked(file: File | undefined) {
    const target = replaceTargetRef.current;
    replaceTargetRef.current = null;
    if (!file || !target) return;
    const confirmation = await Swal.fire({
      icon: "question",
      title: "Replace this evidence file?",
      html: `<span style="font-size:13px">"<b>${file.name}</b>" will be shown (and used on reports) instead of the current file.<br/>The original stays archived and viewable.</span>`,
      showCancelButton: true,
      confirmButtonText: "Replace file",
    });
    if (!confirmation.isConfirmed) return;
    setBusyId(target.evidence_id);
    try {
      await replaceEvidenceFile(target.evidence_id, file);
      await queryClient.invalidateQueries({ queryKey: ["evidence-list"] });
      void Swal.fire({ toast: true, position: "top-end", icon: "success", showConfirmButton: false, timer: 2200, title: "File replaced" });
    } catch (error) {
      await Swal.fire({ icon: "error", title: "Could not replace the file", text: error instanceof Error ? error.message : "" });
    } finally {
      setBusyId(null);
    }
  }

  async function handleReview(item: EvidenceItem, action: "confirm" | "reject") {
    setBusyId(item.evidence_id);
    try {
      await reviewEvidence(item.evidence_id, action);
      await queryClient.invalidateQueries({ queryKey: ["evidence-list"] });
    } catch (error) {
      await Swal.fire({ icon: "error", title: "Could not save the review", text: error instanceof Error ? error.message : "" });
    } finally {
      setBusyId(null);
    }
  }

  async function handleTransfer(item: EvidenceItem) {
    setBusyId(item.evidence_id);
    try {
      const result = await transferEvidence(item.evidence_id);
      await queryClient.invalidateQueries({ queryKey: ["evidence-list"] });
      await queryClient.invalidateQueries({ queryKey: ["manual-rows"] });
      await queryClient.invalidateQueries({ queryKey: ["manual-summary"] });
      void Swal.fire({
        toast: true, position: "top-end", icon: "success", showConfirmButton: false, timer: 2200,
        title: result.already ? `Already on the ${result.month} report` : `Added to the ${result.month} report`,
      });
    } catch (error) {
      await Swal.fire({ icon: "error", title: "Could not transfer", text: error instanceof Error ? error.message : "" });
    } finally {
      setBusyId(null);
    }
  }

  const evidence = useQuery({
    queryKey: ["evidence-list", learner, period],
    queryFn: () => getEvidenceList(learner, period || undefined),
    enabled: Boolean(learner),
    staleTime: 60_000,
  });

  const items = useMemo(() => {
    let list: EvidenceItem[] = evidence.data?.items ?? [];
    if (categoryFilter !== "all") list = list.filter((item) => item.category === categoryFilter);
    if (misfiledOnly) list = list.filter((item) => item.mismatch);
    return list;
  }, [evidence.data, categoryFilter, misfiledOnly]);

  const counts = evidence.data?.counts;
  const total = evidence.data?.total ?? 0;
  const contentClassified = evidence.data?.content_classified ?? 0;
  const misfiled = evidence.data?.misfiled ?? 0;

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="flex w-full flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Evidence explorer</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button type="button" onClick={() => router.history.back()} className="font-medium text-foreground hover:underline">← Back</button>
            <Link to="/journal" search={{ learner, period } as never} className="font-medium hover:underline">Journal</Link>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1500px] space-y-5 px-6 py-8">
        <input
          ref={replaceInputRef}
          type="file"
          className="hidden"
          onChange={(event) => {
            const file = event.target.files?.[0];
            event.target.value = "";
            void handleReplacePicked(file);
          }}
        />
        <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
          <div className="h-1 bg-[#182d48]" />
          <div className="flex flex-wrap items-start justify-between gap-4 px-7 py-6">
            <div>
              <h1 className="text-2xl font-semibold tracking-tight text-[#182d48]">Everything this learner uploaded</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                Classified from the document's own content — the slot it was uploaded into is only a hint.
                {period ? ` Showing ${period}.` : " Showing the whole programme."}
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <span className="rounded-full bg-[#f6f8fb] px-3 py-1.5 font-mono font-medium text-[#182d48]">{total} items</span>
              <span className="rounded-full bg-success/10 px-3 py-1.5 font-mono font-medium text-success" title="Verdict from the content classifier / AI audit">{contentClassified} content-verified</span>
              {misfiled > 0 ? (
                <button type="button" onClick={() => setMisfiledOnly((value) => !value)} className={`flex items-center gap-1 rounded-full px-3 py-1.5 font-semibold ${misfiledOnly ? "bg-destructive text-white" : "bg-destructive/10 text-destructive"}`}>
                  <AlertTriangle className="h-3 w-3" /> {misfiled} misfiled
                </button>
              ) : null}
            </div>
          </div>
          <div className="flex flex-wrap gap-1.5 border-t border-border px-7 py-3">
            <button type="button" onClick={() => setCategoryFilter("all")} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${categoryFilter === "all" ? "bg-[#182d48] text-white" : "bg-[#f6f8fb] text-muted-foreground hover:text-foreground"}`}>
              All ({total})
            </button>
            {counts ? (Object.keys(CATEGORY_LABELS) as EvidenceCategory[]).map((category) => (
              <button key={category} type="button" onClick={() => setCategoryFilter(categoryFilter === category ? "all" : category)} className={`rounded-full px-3 py-1.5 text-xs font-semibold ${categoryFilter === category ? "bg-[#182d48] text-white" : `${CATEGORY_BADGES[category]} hover:opacity-80`}`}>
                {CATEGORY_LABELS[category]} ({counts[category] ?? 0})
              </button>
            )) : null}
          </div>
        </section>

        {!learner ? (
          <p className="py-10 text-center text-sm text-muted-foreground">No learner was provided — open this page from a learner's journal.</p>
        ) : evidence.isLoading ? (
          <p className="py-10 text-center text-sm text-muted-foreground"><LoaderCircle className="mr-2 inline h-4 w-4 animate-spin" />Loading the learner's evidence…</p>
        ) : evidence.isError ? (
          <p className="py-10 text-center text-sm text-destructive">{evidence.error instanceof Error ? evidence.error.message : "Could not load the evidence."}</p>
        ) : !items.length ? (
          <p className="py-10 text-center text-sm text-muted-foreground">Nothing matches this filter.</p>
        ) : (
          <section className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
            <ul className="divide-y divide-border">
              {items.map((item) => (
                <li key={item.evidence_id} className="flex flex-wrap items-start gap-3 px-7 py-3 odd:bg-[#f7f9fc]">
                  {item.kind.toLowerCase() === "note"
                    ? <StickyNote className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
                    : <FileText className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />}
                  <div className="min-w-0 flex-1">
                    {item.has_file ? (
                      <Link to="/doc" search={{ evidence: item.evidence_id, part: "file" } as never} className="block truncate text-sm font-medium text-foreground hover:text-primary hover:underline" title={`Preview ${item.name} in the system`}>
                        {item.name}
                      </Link>
                    ) : (
                      <span className="block truncate text-sm font-medium text-foreground" title={item.name}>{item.name}</span>
                    )}
                    <p className="mt-0.5 truncate text-[11px] text-muted-foreground" title={item.component_name}>
                      Uploaded into: {item.component_name || "—"}
                    </p>
                    {item.note_preview ? <p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{item.note_preview}</p> : null}
                    <div className="mt-1.5 flex flex-wrap items-center gap-1.5">
                      <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${CATEGORY_BADGES[item.category]}`}>{CATEGORY_LABELS[item.category]}</span>
                      {item.category_source.startsWith("hint") || item.category_source === "unresolved" ? (
                        <span className="rounded-full border border-border px-2 py-0.5 text-[10px] font-semibold text-muted-foreground" title="Provisional — the content classifier has not verified this item yet">provisional</span>
                      ) : (
                        <span className="rounded-full bg-success/10 px-2 py-0.5 text-[10px] font-semibold text-success" title={item.confidence != null ? `Content-verified (confidence ${Math.round(item.confidence * 100)}%)` : "Content-verified"}>content ✓</span>
                      )}
                      {item.mismatch ? (
                        <span className="inline-flex items-center gap-1 rounded-full bg-destructive/10 px-2 py-0.5 text-[10px] font-semibold text-destructive" title={item.mismatch_reason ?? "The content does not match the slot it was uploaded into"}>
                          <AlertTriangle className="h-2.5 w-2.5" /> Misfiled
                        </span>
                      ) : null}
                      {item.review_status === "confirmed" ? (
                        <span className="rounded-full bg-success/15 px-2 py-0.5 text-[10px] font-semibold text-success">Reviewed ✓</span>
                      ) : item.review_status === "rejected" ? (
                        <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-semibold text-muted-foreground">Reverted to slot</span>
                      ) : null}
                      {item.status ? <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-semibold text-muted-foreground">{item.status}</span> : null}
                      {item.edited ? (
                        <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] font-semibold text-muted-foreground" title="Name, category or date edited by the audit team">Edited</span>
                      ) : null}
                      {item.replaced ? (
                        <span className="rounded-full bg-amber-500/15 px-2 py-0.5 text-[10px] font-semibold text-amber-700" title={item.replacement_name ? `Current file: ${item.replacement_name}` : "File replaced by the audit team"}>Replaced</span>
                      ) : null}
                      {item.replaced && item.original_has_file ? (
                        <Link to="/doc" search={{ evidence: item.evidence_id, part: "original" } as never} className="rounded-full border border-border px-2 py-0.5 text-[10px] font-semibold text-muted-foreground hover:underline" title="Preview the original Aptem file (kept archived)">View original</Link>
                      ) : null}
                      {item.has_report ? (
                        <Link to="/doc" search={{ evidence: item.evidence_id, part: "report" } as never} className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-semibold text-primary hover:underline">Assessor report</Link>
                      ) : null}
                    </div>
                    {editingId === item.evidence_id ? (
                      <div className="mt-2 flex flex-wrap items-center gap-2 rounded-md border border-primary/30 bg-primary/5 px-2.5 py-2">
                        <input value={editDraft.display_name} maxLength={500} onChange={(event) => setEditDraft((draft) => ({ ...draft, display_name: event.target.value }))} className="h-8 min-w-56 flex-1 rounded-md border border-border bg-card px-2 text-xs outline-none focus:border-primary" aria-label="Evidence name" />
                        <select value={editDraft.category} onChange={(event) => setEditDraft((draft) => ({ ...draft, category: event.target.value as EvidenceCategory }))} className="h-8 rounded-md border border-border bg-card px-2 text-xs" aria-label="Evidence category">
                          {(Object.keys(CATEGORY_LABELS) as EvidenceCategory[]).map((category) => (
                            <option key={category} value={category}>{CATEGORY_LABELS[category]}</option>
                          ))}
                        </select>
                        <input type="date" value={editDraft.evidence_date} onChange={(event) => setEditDraft((draft) => ({ ...draft, evidence_date: event.target.value }))} className="h-8 rounded-md border border-border bg-card px-2 text-xs" aria-label="Evidence date" />
                        <button type="button" disabled={busyId === item.evidence_id} onClick={() => void saveEdit()} className="flex items-center gap-1 rounded-md bg-primary px-2.5 py-1 text-[11px] font-semibold text-primary-foreground hover:opacity-90 disabled:opacity-50">
                          <Check className="h-3 w-3" /> Save
                        </button>
                        <button type="button" onClick={() => setEditingId(null)} className="flex items-center gap-1 rounded-md border border-border bg-card px-2.5 py-1 text-[11px] font-semibold text-foreground hover:bg-secondary">
                          <X className="h-3 w-3" /> Cancel
                        </button>
                      </div>
                    ) : null}
                    {item.mismatch && !item.review_status ? (
                      <div className="mt-2 flex flex-wrap items-center gap-2 rounded-md border border-destructive/25 bg-destructive/5 px-2.5 py-1.5">
                        <span className="text-[11px] font-medium text-foreground">
                          Uploaded as: <span className={`rounded px-1.5 py-0.5 font-semibold ${CATEGORY_BADGES[item.slot_category]}`}>{CATEGORY_LABELS[item.slot_category]}</span>
                          <span className="mx-1.5 text-muted-foreground">→</span>
                          Classified as: <span className={`rounded px-1.5 py-0.5 font-semibold ${CATEGORY_BADGES[item.category]}`}>{CATEGORY_LABELS[item.category]}</span>
                        </span>
                        <span className="flex-1" />
                        <button type="button" disabled={busyId === item.evidence_id} onClick={() => void handleReview(item, "confirm")} className="flex items-center gap-1 rounded-md bg-success px-2.5 py-1 text-[11px] font-semibold text-white hover:opacity-90 disabled:opacity-50">
                          <Check className="h-3 w-3" /> Confirm
                        </button>
                        <button type="button" disabled={busyId === item.evidence_id} onClick={() => void handleReview(item, "reject")} className="flex items-center gap-1 rounded-md border border-border bg-card px-2.5 py-1 text-[11px] font-semibold text-foreground hover:bg-secondary disabled:opacity-50">
                          <Undo2 className="h-3 w-3" /> Keep slot type
                        </button>
                      </div>
                    ) : null}
                    <div className="mt-1.5">
                      {item.report_month ? (
                        <span className="rounded-full bg-success/10 px-2 py-0.5 text-[10px] font-semibold text-success">On the {item.report_month} report ✓</span>
                      ) : (
                        <button type="button" disabled={busyId === item.evidence_id} onClick={() => void handleTransfer(item)} className="rounded-md border border-[#182d48]/30 bg-card px-2.5 py-1 text-[11px] font-semibold text-[#182d48] hover:bg-secondary disabled:opacity-50">
                          {busyId === item.evidence_id ? "Transferring…" : "→ Transfer to monthly report"}
                        </button>
                      )}
                    </div>
                  </div>
                  <div className="shrink-0 text-right">
                    <p className="font-mono text-xs text-muted-foreground">{item.date ?? "—"}</p>
                    <p className="mt-1 font-mono text-sm font-semibold text-[#182d48]" title="Evidenced OTJH time">{hoursLabel(item.otjh_hours)}</p>
                    <div className="mt-2 flex justify-end gap-1">
                      <button type="button" disabled={busyId === item.evidence_id} onClick={() => startEdit(item)} className="rounded-md border border-border p-1.5 text-muted-foreground hover:bg-secondary hover:text-foreground disabled:opacity-50" title="Edit name, category or date" aria-label={`Edit ${item.name}`}>
                        <Pencil className="h-3.5 w-3.5" />
                      </button>
                      <button type="button" disabled={busyId === item.evidence_id} onClick={() => pickReplacement(item)} className="rounded-md border border-border p-1.5 text-muted-foreground hover:bg-secondary hover:text-foreground disabled:opacity-50" title="Upload a file that replaces the current one (the original stays archived)" aria-label={`Replace file of ${item.name}`}>
                        <Upload className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </section>
        )}

        <p className="pb-4 text-xs text-muted-foreground">
          Files and assessor reports open inside the system. "Provisional" items are labelled from their slot/file name until the content classifier verifies them.
        </p>
      </main>
    </div>
  );
}
